   144|/**
   145| * ROOT-CAUSE FIX (2026-06-10) — "backend replied, but I couldn't read its
   146| * response." When a real 2xx reply (especially Owner Execution Mode / audit
   147| * answers) contained structured metadata lines (`detected_intent:`,
   148| * `selected_route:`, `source: owner_audit_report`, ...) or fallback markers,
   149| * the blocked-text guard rejected the ENTIRE response. Both the canonical
   150| * validator and the compatibility extractor then threw, dead-ending the send
   151| * on the parse-error message instead of rendering the real answer.
   152| *
   153| * Instead of discarding the whole reply, strip ONLY the offending lines and
   154| * keep the rest. If meaningful text remains, it renders. Returns '' when there
   155| * is nothing safe left to show (caller then falls back to proof synthesis).
   156| */
   157|export function sanitizeOwnerAIVisibleText(value: unknown): string {
   158|  if (typeof value !== 'string') {
   159|    return '';
   160|  }
   161|  const trimmed = value.trim();
   162|  if (!trimmed) {
   163|    return '';
   164|  }
   165|  if (!containsBlockedOwnerAIResponseText(trimmed)) {
   166|    return trimmed;
   167|  }
   168|  const kept = trimmed
   169|    .split('\n')
   170|    .filter((line) => !BLOCKED_VISIBLE_RESPONSE_PATTERNS.some((pattern) => pattern.test(line)));
   171|  return kept.join('\n').trim();
   172|}
