   174|function readProofString(record: Record<string, unknown>, ...keys: string[]): string | undefined {
   175|  for (const key of keys) {
   176|    const value = record[key];
   177|    if (typeof value === 'string' && value.trim().length > 0) {
   178|      return value.trim();
   179|    }
   180|  }
   181|  return undefined;
   182|}
