   184|/**
   185| * ROOT-CAUSE FIX (2026-06-10) — render Owner Execution Mode proof payloads.
   186| * When the backend returns job/proof data (jobId, traceId, filesChanged,
   187| * tests, deployment) on a 2xx body but no clean prose `answer`, build a
   188| * readable owner-facing summary so the chat renders the proof instead of
   189| * throwing "couldn't read its response."
   190| */
   191|function synthesizeOwnerAIProofAnswer(record: Record<string, unknown> | null): string {
   192|  if (!record) {
   193|    return '';
   194|  }
   195|  const lines: string[] = [];
   196|  const jobId = readProofString(record, 'jobId', 'job_id');
   197|  const traceId = readProofString(record, 'traceId', 'trace_id');
   198|  const status = readProofString(record, 'status');
   199|  const filesChanged = Array.isArray(record.filesChanged)
   200|    ? record.filesChanged
   201|    : Array.isArray(record.files_changed)
   202|      ? record.files_changed
   203|      : undefined;
   204|  const tests = record.tests;
   205|  const deployment = record.deployment;
   206|
   207|  if (jobId) {
   208|    lines.push(`Job: ${jobId}`);
   209|  }
   210|  if (traceId) {
   211|    lines.push(`Trace: ${traceId}`);
   212|  }
   213|  if (status) {
   214|    lines.push(`Status: ${status}`);
   215|  }
   216|  if (filesChanged && filesChanged.length > 0) {
   217|    const fileList = filesChanged
   218|      .filter((file): file is string => typeof file === 'string')
   219|      .map((file) => `  - ${file}`);
   220|    if (fileList.length > 0) {
   221|      lines.push(`Files changed (${fileList.length}):`, ...fileList);
   222|    }
   223|  }
   224|  if (isRecord(tests)) {
   225|    lines.push(`Tests: ${JSON.stringify(tests).slice(0, 600)}`);
   226|  }
   227|  if (isRecord(deployment)) {
   228|    lines.push(`Deployment: ${JSON.stringify(deployment).slice(0, 600)}`);
   229|  }
   230|
   231|  if (lines.length === 0) {
   232|    return '';
   233|  }
   234|  return ['IVX Owner AI returned an execution result:', '', ...lines].join('\n');
   235|}
