     1|/**
     2| * Owner-only distribution presign endpoint (APK/AAB releases + landing assets).
     3| *
     4| * Mints a short-lived (15 min) presigned S3 PUT URL restricted to either the
     5| * `apk/` prefix (release artifacts) or an explicit whitelist of top-level
     6| * landing-page files, so a build agent can upload WITHOUT AWS credentials
     7| * ever leaving the runtime.
     8| *
     9| * Guards:
    10| *  - Registered owner bearer required (assertIVXRegisteredOwnerBearer)
    11| *  - Explicit per-class confirmation phrase (409 without it):
    12| *      apk/<name>.(apk|aab)      -> CONFIRM_IVX_APK_UPLOAD
    13| *      landing whitelist file    -> CONFIRM_IVX_LANDING_UPLOAD
    14| *  - Secrets are never returned; only the signed URL is.
    15| */
    16|import { createHash, createHmac } from 'node:crypto';
    17|
    18|import { getRawOwnerVariableValue } from './ivx-owner-variables';
    19|import { IVXOwnerApprovalError, assertIVXRegisteredOwnerBearer, ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    20|
    21|const IVX_APK_UPLOAD_CONFIRM_PHRASE = 'CONFIRM_IVX_APK_UPLOAD';
    22|const IVX_LANDING_UPLOAD_CONFIRM_PHRASE = 'CONFIRM_IVX_LANDING_UPLOAD';
    23|const IVX_APK_KEY_PATTERN = /^apk\/[A-Za-z0-9][A-Za-z0-9._-]{0,120}\.(apk|aab)$/;
    24|/** Top-level landing-page assets only — no prefixes, no traversal, tight extension set. */
    25|const IVX_LANDING_KEY_PATTERN = /^(index\.html|robots\.txt|sitemap\.xml|ivx-[a-z0-9-]{1,60}\.(js|json)|landing-support-chat\.(js|css))$/;
    26|const IVX_APK_PRESIGN_EXPIRES_SECONDS = 900;
    27|const IVX_APK_BUCKET_DEFAULT = 'ivxholding.com';
    28|
    29|export function OPTIONS(): Response {
    30|  return ownerOnlyOptions();
    31|}
    32|
    33|function readEnv(name: string): string {
    34|  return (process.env[name] ?? '').trim();
    35|}
    36|
    37|type PresignInput = {
    38|  bucket: string;
    39|  region: string;
    40|  key: string;
    41|  accessKeyId: string;
    42|  secretAccessKey: string;
    43|  expiresSeconds: number;
    44|  now: Date;
    45|};
    46|
    47|function hmac(key: Buffer | string, value: string): Buffer {
    48|  return createHmac('sha256', key).update(value).digest();
    49|}
    50|
    51|function sha256Hex(value: string): string {
    52|  return createHash('sha256').update(value).digest('hex');
    53|}
    54|
    55|/**
    56| * Build a SigV4 query-string presigned PUT URL (UNSIGNED-PAYLOAD, host-only
    57| * signed header). Pure and deterministic for a fixed `now` so it is unit-testable.
    58| *
    59| * Uses PATH-STYLE addressing (s3.<region>.amazonaws.com/<bucket>/<key>) because
    60| * bucket names containing dots (e.g. `ivxholding.com`) break TLS on the
    61| * virtual-hosted wildcard certificate (*.s3.<region>.amazonaws.com).
    62| */
    63|export function buildIVXS3PresignedPutUrl(input: PresignInput): string {
    64|  const amzDate = input.now.toISOString().replace(/[:.-]/g, '').slice(0, 15) + 'Z';
    65|  const dateStamp = amzDate.slice(0, 8);
    66|  const host = `s3.${input.region}.amazonaws.com`;
    67|  const credentialScope = `${dateStamp}/${input.region}/s3/aws4_request`;
    68|
    69|  const queryEntries: [string, string][] = [
    70|    ['X-Amz-Algorithm', 'AWS4-HMAC-SHA256'],
    71|    ['X-Amz-Credential', `${input.accessKeyId}/${credentialScope}`],
    72|    ['X-Amz-Date', amzDate],
    73|    ['X-Amz-Expires', String(input.expiresSeconds)],
    74|    ['X-Amz-SignedHeaders', 'host'],
    75|  ];
    76|  const canonicalQuery = queryEntries
    77|    .map(([name, value]) => `${encodeURIComponent(name)}=${encodeURIComponent(value)}`)
    78|    .sort()
    79|    .join('&');
    80|
    81|  const canonicalRequest = [
    82|    'PUT',
    83|    `/${input.bucket}/${input.key}`,
    84|    canonicalQuery,
    85|    `host:${host}\n`,
    86|    'host',
    87|    'UNSIGNED-PAYLOAD',
    88|  ].join('\n');
    89|
    90|  const stringToSign = [
    91|    'AWS4-HMAC-SHA256',
    92|    amzDate,
    93|    credentialScope,
    94|    sha256Hex(canonicalRequest),
    95|  ].join('\n');
    96|
    97|  const signingKey = hmac(hmac(hmac(hmac(`AWS4${input.secretAccessKey}`, dateStamp), input.region), 's3'), 'aws4_request');
    98|  const signature = createHmac('sha256', signingKey).update(stringToSign).digest('hex');
    99|
   100|  return `https://${host}/${input.bucket}/${input.key}?${canonicalQuery}&X-Amz-Signature=${signature}`;
   101|}
   102|
   103|export function isValidIVXApkDistributionKey(key: string): boolean {
   104|  return IVX_APK_KEY_PATTERN.test(key);
   105|}
   106|
   107|export function isValidIVXLandingDistributionKey(key: string): boolean {
   108|  return IVX_LANDING_KEY_PATTERN.test(key);
   109|}
   110|
   111|type PresignRequestBody = {
   112|  key?: string;
   113|  confirm?: boolean;
   114|  confirmText?: string;
   115|};
   116|
   117|export async function handleIVXApkPresignUploadRequest(request: Request): Promise<Response> {
   118|  let approval;
   119|  try {
   120|    approval = await assertIVXRegisteredOwnerBearer(request, 'apk_presign_upload');
   121|  } catch (error) {
   122|    if (error instanceof IVXOwnerApprovalError) {
   123|      return ownerOnlyJson({ status: 'error', error: error.message, approval: error.proof }, error.status);
   124|    }
   125|    return ownerOnlyJson({ status: 'error', error: error instanceof Error ? error.message : 'Owner verification failed.' }, 403);
   126|  }
   127|
   128|  let body: PresignRequestBody = {};
   129|  try {
   130|    body = await request.json() as PresignRequestBody;
   131|  } catch {
   132|    // handled below via validation
   133|  }
   134|
   135|  const key = (body.key ?? '').trim();
   136|  const isApkKey = isValidIVXApkDistributionKey(key);
   137|  const isLandingKey = !isApkKey && isValidIVXLandingDistributionKey(key);
   138|  if (!isApkKey && !isLandingKey) {
   139|    return ownerOnlyJson({
   140|      status: 'error',
   141|      error: 'INVALID_KEY',
   142|      detail: 'Key must match apk/<name>.(apk|aab) or a whitelisted top-level landing file (index.html, robots.txt, sitemap.xml, ivx-*.js/json, landing-support-chat.js/css).',
   143|    }, 400);
   144|  }
   145|
   146|  const requiredPhrase = isApkKey ? IVX_APK_UPLOAD_CONFIRM_PHRASE : IVX_LANDING_UPLOAD_CONFIRM_PHRASE;
   147|  if (body.confirm !== true || (body.confirmText ?? '').trim() !== requiredPhrase) {
   148|    return ownerOnlyJson({
   149|      status: 'error',
   150|      error: 'confirmationRequired',
   151|      detail: `Pass confirm:true and confirmText:"${requiredPhrase}" to mint an upload URL for this key.`,
   152|    }, 409);
   153|  }
   154|
   155|  const region = readEnv('AWS_REGION') || 'us-east-1';
   156|  const bucket = readEnv('S3_BUCKET_NAME') || IVX_APK_BUCKET_DEFAULT;
   157|  let accessKeyId = readEnv('AWS_ACCESS_KEY_ID');
   158|  let secretAccessKey = readEnv('AWS_SECRET_ACCESS_KEY');
   159|  if (!accessKeyId) accessKeyId = await getRawOwnerVariableValue('AWS_ACCESS_KEY_ID');
   160|  if (!secretAccessKey) secretAccessKey = await getRawOwnerVariableValue('AWS_SECRET_ACCESS_KEY');
   161|
   162|  if (!accessKeyId || !secretAccessKey) {
   163|    return ownerOnlyJson({
   164|      status: 'error',
   165|      error: 'AWS_CREDENTIALS_MISSING',
   166|      detail: 'AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY are not available on this runtime.',
   167|    }, 500);
   168|  }
   169|
   170|  const uploadUrl = buildIVXS3PresignedPutUrl({
   171|    bucket,
   172|    region,
   173|    key,
   174|    accessKeyId,
   175|    secretAccessKey,
   176|    expiresSeconds: IVX_APK_PRESIGN_EXPIRES_SECONDS,
   177|    now: new Date(),
   178|  });
   179|
   180|  return ownerOnlyJson({
   181|    status: 'ok',
